import math

def matern(x,y):
 r=math.sqrt(sum((a-b)**2 for a,b in zip(x,y)))
 return (1+math.sqrt(5)*r+5*r*r/3)*math.exp(-math.sqrt(5)*r)

def mixed_trace(x,y,h=1e-4):
 out=0.0
 for j in range(len(x)):
  xp=x.copy(); xm=x.copy(); yp=y.copy(); ym=y.copy()
  xp[j]+=h; xm[j]-=h; yp[j]+=h; ym[j]-=h
  out+=(matern(xp,yp)-matern(xp,ym)-matern(xm,yp)+matern(xm,ym))/(4*h*h)
 return out
for d in (1,2,3):
 z=[0.0]*d
 print(f'Matern mixed trace at x=xprime, dimension {d}: numerical={mixed_trace(z,z):.6f}, Appendix C.1={5/3:.6f}, corrected={5*d/3:.6f}')
for kval in (0.3,2.0,10.0):
 increment=2.75
 cf_est=(increment/kval)/(1/kval)
 print(f'One-point Eq.11: kernel={kval}, increment={increment}, estimate={cf_est}')
